package snapshots

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

const historyRoutingRetiredScanLimit = 256
const historyRoutingRetiredFileLimit = 16
const historyRoutingPublishedBudget = 128 << 20

type historyRoutingRetiredResult struct {
	Next         retiredMetadataSweepCursor
	Scanned      int
	FilesDeleted int
	BytesDeleted uint64
	Deferred     bool
}

// These objects contain no before-images or canonical state. Deleting an
// unpublished retired routing object never removes a fallback source. Keep
// canonical retirement's exhaustive authentication gate entirely separate.
func historyRoutingRetiredObject(ref SegmentRef) bool {
	if ref.normalizedDataset() != SegmentDatasetStateDomainChange {
		return false
	}
	digest, ok := snapshotChecksumDigest(ref.Checksum)
	if !ok || len(digest) != 64 || !strings.HasPrefix(ref.Checksum, "sha256:") {
		return false
	}
	prefix := ""
	switch ref.Kind {
	case SegmentSystemHistoryRouting:
		prefix = "system-routing"
	case SegmentAccountHistoryRouting:
		prefix = "account-routing"
	default:
		return false
	}
	return ref.Path == fmt.Sprintf("history/%s-%d-%d-%s.route", prefix, ref.FromTxNum, ref.ToTxNum, digest)
}

// Caller holds Runner.passMu and the heavy-work lease. A cursor bounds metadata
// work; at most sixteen files are unlinked. Missing rows remain in Retired for
// the existing bounded metadata sweep. No manifest/frontier/commitment changes.
func pruneRetiredHistoryRoutingContext(ctx context.Context, dir string, cursor retiredMetadataSweepCursor) (result historyRoutingRetiredResult, err error) {
	if ctx == nil {
		ctx = context.Background()
	}
	result.Next = cursor
	if err = contextError(ctx); err != nil {
		return result, err
	}
	release, acquired := tryHistoryRetirement()
	if !acquired {
		result.Deferred = true
		return result, nil
	}
	defer release()
	if !manifestPublicationMu.TryLock() {
		result.Deferred = true
		return result, nil
	}
	defer manifestPublicationMu.Unlock()
	root, e := os.Lstat(dir)
	parent, pe := os.Lstat(filepath.Join(dir, "history"))
	if e != nil || pe != nil || !root.IsDir() || !parent.IsDir() || root.Mode()&os.ModeSymlink != 0 || parent.Mode()&os.ModeSymlink != 0 {
		result.Deferred = true
		return result, nil
	}
	for _, name := range []string{historyReferenceMigrationJournalFile, historyCDCMigrationJournalFile} {
		if _, e := os.Lstat(filepath.Join(dir, name)); !os.IsNotExist(e) {
			result.Deferred = true
			return result, nil
		}
	}
	manifest, err := loadProductionManifestReadOnly(dir)
	if os.IsNotExist(err) {
		return result, nil
	}
	if err != nil {
		return result, err
	}
	chunks, next := retiredMetadataSweepChunks(manifest.Retired, cursor, historyRoutingRetiredScanLimit)
	candidates := make(map[string]SegmentRef)
	for _, chunk := range chunks {
		result.Scanned += chunk.end - chunk.start
		for _, ref := range manifest.Retired[chunk.start:chunk.end] {
			if historyRoutingRetiredObject(ref) {
				candidates[ref.Path] = ref
			}
		}
	}
	for _, ref := range manifest.Segments {
		delete(candidates, ref.Path)
	}
	// Even a malformed duplicate retired identity cannot authorize deletion of
	// a canonical recovery object that happens to use the same path.
	for _, ref := range manifest.Retired {
		if !historyRoutingRetiredObject(ref) {
			delete(candidates, ref.Path)
		}
	}
	if len(candidates) == 0 {
		result.Next = next
		return result, nil
	}
	if ok, e := protectPublishedRoutingObjects(ctx, dir, candidates); e != nil || !ok {
		result.Deferred = true
		return result, e
	}
	for path, ref := range candidates {
		if result.FilesDeleted >= historyRoutingRetiredFileLimit {
			break
		}
		if err := contextError(ctx); err != nil {
			return result, err
		}
		full := filepath.Join(dir, path)
		before, e := os.Lstat(full)
		if os.IsNotExist(e) {
			continue
		}
		if e != nil {
			return result, e
		}
		if !before.Mode().IsRegular() || before.Size() < 8 || uint64(before.Size()) != ref.Size {
			continue
		}
		f, e := os.Open(full)
		if e != nil {
			return result, e
		}
		var magic [8]byte
		_, readErr := io.ReadFull(f, magic[:])
		inspected, statErr := f.Stat()
		closeErr := f.Close()
		want := systemHistoryRoutingMagic
		if ref.Kind == SegmentAccountHistoryRouting {
			want = accountRoutingMagic
		}
		if readErr != nil || statErr != nil || closeErr != nil || !os.SameFile(before, inspected) || !bytes.Equal(magic[:], want[:]) {
			continue
		}
		after, e := os.Lstat(full)
		currentRoot, re := os.Lstat(dir)
		currentParent, de := os.Lstat(filepath.Join(dir, "history"))
		if e != nil || re != nil || de != nil || !os.SameFile(before, after) || !os.SameFile(root, currentRoot) || !os.SameFile(parent, currentParent) {
			result.Deferred = true
			return result, nil
		}
		if err := contextError(ctx); err != nil {
			return result, err
		}
		if e := os.Remove(full); e != nil {
			return result, e
		}
		result.FilesDeleted++
		result.BytesDeleted += ref.Size
	}
	if result.FilesDeleted > 0 {
		if err := syncSnapshotDir(filepath.Join(dir, "history")); err != nil {
			return result, err
		}
	}
	result.Next = next
	return result, nil
}

// Decode one bounded immutable generation at a time. Validate its entire JSON
// and content-addressed name before trusting absence. A legacy mutable catalog
// or an oversized collection defers this optional cleanup without weakening
// the ordinary snapshot/retirement verifier.
func protectPublishedRoutingObjects(ctx context.Context, dir string, candidates map[string]SegmentRef) (bool, error) {
	catalogPath, catalogChecksum := "", ""
	if data, within, err := readRoutingRetiredMetadata(ctx, filepath.Join(dir, SnapshotCatalogFile), 1<<20); err == nil {
		if !within {
			return false, nil
		}
		var catalog SnapshotCatalog
		if err := json.Unmarshal(data, &catalog); err != nil {
			return false, err
		}
		if err := catalog.Validate(); err != nil {
			return false, err
		}
		if catalog.ManifestPath == ManifestFile {
			return false, nil
		}
		catalogPath, catalogChecksum = catalog.ManifestPath, catalog.ManifestChecksum
	} else if !os.IsNotExist(err) {
		return false, err
	}
	root := filepath.Join(dir, SnapshotPublishedDir)
	rootInfo, err := os.Lstat(root)
	if os.IsNotExist(err) {
		return catalogPath == "", nil
	}
	if err != nil {
		return false, err
	}
	if !rootInfo.IsDir() || rootInfo.Mode()&os.ModeSymlink != 0 {
		return false, nil
	}
	directory, err := os.Open(root)
	if os.IsNotExist(err) {
		return catalogPath == "", nil
	}
	if err != nil {
		return false, err
	}
	openedInfo, statErr := directory.Stat()
	if statErr != nil || !os.SameFile(rootInfo, openedInfo) {
		directory.Close()
		return false, statErr
	}
	entries, err := directory.ReadDir(65)
	closeErr := directory.Close()
	if err != nil && err != io.EOF {
		return false, err
	}
	if closeErr != nil || len(entries) > 64 {
		return false, closeErr
	}
	remaining := int64(historyRoutingPublishedBudget)
	catalogFound := catalogPath == ""
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasPrefix(entry.Name(), "manifest-") || !strings.HasSuffix(entry.Name(), ".json") {
			continue
		}
		if err := contextError(ctx); err != nil {
			return false, err
		}
		info, err := entry.Info()
		if err != nil {
			return false, err
		}
		if !info.Mode().IsRegular() || info.Size() < 0 || info.Size() > remaining {
			return false, nil
		}
		remaining -= info.Size()
		data, within, err := readRoutingRetiredMetadata(ctx, filepath.Join(root, entry.Name()), info.Size())
		if err != nil {
			return false, err
		}
		if !within || int64(len(data)) != info.Size() {
			return false, nil
		}
		m, err := decodeProductionManifest(data)
		if err != nil {
			return false, err
		}
		want, err := publishedSnapshotManifestPath(m.Generation, checksumBytes(data))
		if err != nil || want != filepath.ToSlash(filepath.Join(SnapshotPublishedDir, entry.Name())) {
			return false, fmt.Errorf("snapshots: routing retirement encountered an invalid published generation")
		}
		if want == catalogPath {
			if checksumBytes(data) != catalogChecksum {
				return false, fmt.Errorf("snapshots: routing retirement catalog checksum mismatch")
			}
			catalogFound = true
		}
		for _, ref := range m.Segments {
			delete(candidates, ref.Path)
		}
	}
	return catalogFound, nil
}

func readRoutingRetiredMetadata(ctx context.Context, path string, limit int64) ([]byte, bool, error) {
	before, err := os.Lstat(path)
	if err != nil {
		return nil, false, err
	}
	if !before.Mode().IsRegular() {
		return nil, false, nil
	}
	f, err := os.Open(path)
	if err != nil {
		return nil, false, err
	}
	defer f.Close()
	opened, err := f.Stat()
	if err != nil || !os.SameFile(before, opened) {
		return nil, false, err
	}
	data, err := io.ReadAll(io.LimitReader(contextReader{ctx: ctx, r: f}, limit+1))
	return data, int64(len(data)) <= limit, err
}

package snapshots

import (
	"bytes"
	"context"
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"testing"
)

func retiredRoutingFixture(t *testing.T) (string, *Manifest, SegmentRef) {
	t.Helper()
	dir, m, _ := accountRoutingFixture(t, 9)
	m = addAccountRoutingFixture(t, dir, m, 1)
	old := mustAccountRoutingRef(t, m)
	m = addAccountRoutingFixture(t, dir, m, 64)
	return dir, m, old
}

func TestRetiredHistoryRoutingOnlyDeletesUnleasedAuxiliaryFiles(t *testing.T) {
	dir, m, old := retiredRoutingFixture(t)
	before, err := os.ReadFile(filepath.Join(dir, ManifestFile))
	if err != nil {
		t.Fatal(err)
	}
	canonical := make(map[string][32]byte)
	for _, ref := range m.Segments {
		if ref.Kind != SegmentAccountHistoryRouting {
			data, err := os.ReadFile(filepath.Join(dir, ref.Path))
			if err != nil {
				t.Fatal(err)
			}
			canonical[ref.Path] = sha256.Sum256(data)
		}
	}
	result, err := pruneRetiredHistoryRoutingContext(context.Background(), dir, retiredMetadataSweepCursor{})
	if err != nil || result.FilesDeleted != 1 || result.BytesDeleted != old.Size {
		t.Fatalf("prune=%+v err=%v", result, err)
	}
	if _, err := os.Stat(filepath.Join(dir, old.Path)); !os.IsNotExist(err) {
		t.Fatal("old auxiliary file retained", err)
	}
	if _, err := os.Stat(filepath.Join(dir, mustAccountRoutingRef(t, m).Path)); err != nil {
		t.Fatal("active index lost", err)
	}
	after, err := os.ReadFile(filepath.Join(dir, ManifestFile))
	if err != nil || !bytes.Equal(before, after) {
		t.Fatal("cleanup changed signed metadata", err)
	}
	for path, want := range canonical {
		data, err := os.ReadFile(filepath.Join(dir, path))
		if err != nil || sha256.Sum256(data) != want {
			t.Fatal("canonical file changed", path, err)
		}
	}
	if err := checkAccountHistoryRoutingContext(context.Background(), dir, m, mustAccountRoutingRef(t, m)); err != nil {
		t.Fatal(err)
	}
}

func TestRetiredHistoryRoutingPinsReadersAndPublishedGenerations(t *testing.T) {
	dir, m, old := retiredRoutingFixture(t)
	r, err := OpenManager(dir)
	if err != nil {
		t.Fatal(err)
	}
	_, release, err := r.PinHistoryReadView()
	if err != nil {
		t.Fatal(err)
	}
	result, err := pruneRetiredHistoryRoutingContext(context.Background(), dir, retiredMetadataSweepCursor{})
	release()
	if err != nil || !result.Deferred || result.FilesDeleted != 0 {
		t.Fatalf("reader lease: %+v %v", result, err)
	}
	published := cloneManifest(m)
	for i, ref := range published.Segments {
		if ref.Kind == SegmentAccountHistoryRouting {
			published.Segments[i] = old
		}
	}
	data, err := json.Marshal(published)
	if err != nil {
		t.Fatal(err)
	}
	name, err := publishedSnapshotManifestPath(published.Generation, checksumBytes(data))
	if err != nil {
		t.Fatal(err)
	}
	if err := publishImmutableSnapshotManifest(dir, name, data); err != nil {
		t.Fatal(err)
	}
	result, err = pruneRetiredHistoryRoutingContext(context.Background(), dir, retiredMetadataSweepCursor{})
	if err != nil || result.FilesDeleted != 0 {
		t.Fatalf("published lease: %+v %v", result, err)
	}
	if _, err := os.Stat(filepath.Join(dir, old.Path)); err != nil {
		t.Fatal(err)
	}
}

func TestRetiredHistoryRoutingCancellationMigrationAndBadLeases(t *testing.T) {
	for _, mode := range []string{"cancel", "migration", "bad-published", "many-published", "symlink", "catalog-symlink"} {
		t.Run(mode, func(t *testing.T) {
			dir, _, old := retiredRoutingFixture(t)
			ctx, cancel := context.WithCancel(context.Background())
			defer cancel()
			switch mode {
			case "cancel":
				cancel()
			case "migration":
				if err := os.WriteFile(filepath.Join(dir, historyReferenceMigrationJournalFile), nil, 0600); err != nil {
					t.Fatal(err)
				}
			case "bad-published", "many-published":
				root := filepath.Join(dir, SnapshotPublishedDir)
				if err := os.MkdirAll(root, 0755); err != nil {
					t.Fatal(err)
				}
				if mode == "bad-published" {
					if err := os.WriteFile(filepath.Join(root, "manifest-bad.json"), []byte("{}"), 0600); err != nil {
						t.Fatal(err)
					}
				} else {
					for i := 0; i < 65; i++ {
						if err := os.WriteFile(filepath.Join(root, fmt.Sprint(i)), nil, 0600); err != nil {
							t.Fatal(err)
						}
					}
				}
			case "symlink":
				path := filepath.Join(dir, old.Path)
				if err := os.Rename(path, path+".saved"); err != nil {
					t.Fatal(err)
				}
				if err := os.Symlink(path+".saved", path); err != nil {
					t.Fatal(err)
				}
			case "catalog-symlink":
				if err := os.Symlink(filepath.Join(dir, "absent"), filepath.Join(dir, SnapshotCatalogFile)); err != nil {
					t.Fatal(err)
				}
			}
			result, err := pruneRetiredHistoryRoutingContext(ctx, dir, retiredMetadataSweepCursor{})
			if result.FilesDeleted != 0 {
				t.Fatal("protected object deleted", result)
			}
			if mode == "cancel" && !errors.Is(err, context.Canceled) {
				t.Fatal(err)
			}
			if _, e := os.Lstat(filepath.Join(dir, old.Path)); e != nil {
				t.Fatal(e)
			}
		})
	}
}

func TestRetiredHistoryRoutingBoundsCursorAndIdentity(t *testing.T) {
	dir, m, _ := retiredRoutingFixture(t)
	for i := 0; i < 300; i++ {
		data := append(append([]byte(nil), accountRoutingMagic[:]...), []byte(fmt.Sprint(i))...)
		sum := sha256.Sum256(data)
		ref := SegmentRef{Dataset: SegmentDatasetStateDomainChange, Kind: SegmentAccountHistoryRouting, FromTxNum: 1, ToTxNum: 3, Size: uint64(len(data)), Checksum: fmt.Sprintf("sha256:%x", sum), LookupRoot: fmt.Sprintf("sha256:%x", sum), Path: fmt.Sprintf("history/account-routing-1-3-%x.route", sum)}
		if !historyRoutingRetiredObject(ref) {
			t.Fatal("bad fixture identity")
		}
		if err := os.WriteFile(filepath.Join(dir, ref.Path), data, 0600); err != nil {
			t.Fatal(err)
		}
		m.Retired = append(m.Retired, ref)
	}
	if err := PublishManifest(dir, m); err != nil {
		t.Fatal(err)
	}
	var cursor retiredMetadataSweepCursor
	deleted := 0
	for pass := 0; pass < 100; pass++ {
		r, err := pruneRetiredHistoryRoutingContext(context.Background(), dir, cursor)
		if err != nil {
			t.Fatal(err)
		}
		if r.Scanned > historyRoutingRetiredScanLimit || r.FilesDeleted > historyRoutingRetiredFileLimit {
			t.Fatal("unbounded cleanup", r)
		}
		cursor = r.Next
		deleted += r.FilesDeleted
	}
	if deleted != 301 {
		t.Fatalf("cursor starved: removed %d", deleted)
	}
	bad := mustAccountRoutingRef(t, m)
	bad.Path = "history/state-domain-change.seg"
	if historyRoutingRetiredObject(bad) {
		t.Fatal("canonical path accepted")
	}
	before := cloneManifest(m).Progress
	after, err := LoadProductionManifest(dir)
	if err != nil || !reflect.DeepEqual(before, after.Progress) {
		t.Fatal("frontier changed", err)
	}
}

func TestSnapshotCatalogPublisherDefersDuringPhysicalRetirement(t *testing.T) {
	release, ok := tryHistoryRetirement()
	if !ok {
		t.Fatal("exclusive fixture lease")
	}
	defer release()
	_, err := PublishSignedSnapshotCatalog(t.TempDir(), ed25519.NewKeyFromSeed(make([]byte, ed25519.SeedSize)))
	if !errors.Is(err, ErrHistoryReadLeaseBusy) {
		t.Fatal("publisher did not pin files", err)
	}
}
